bn-abc.css:
.card {
  text-align: center;
  font-size: 17px;
  line-height: 1.6;
}
.uc-ask {
  margin-bottom: 14px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
}
.uc-letter {
  font-size: 60px;
  font-weight: 400;
  line-height: 1.3;
}
.uc-rule {
  font-size: 34px;
  line-height: 1.5;
}
.uc-say {
  margin-left: 14px;
  vertical-align: middle;
  font-size: 15px;
}
.uc-exsay {
  margin: 0 8px 0 6px;
  vertical-align: middle;
  font-size: 13px;
}
.uc-field {
  display: block;
  width: fit-content;
  min-width: min(300px, 100%);
  max-width: 100%;
  margin: 14px auto 0;
  padding: 11px 15px;
  border: 1px solid var(--rule, rgba(0,0,0,0.12));
  border-radius: 11px;
  text-align: left;
  background: color-mix(in srgb, var(--paper-2, #EFEDE6) 58%, var(--card, #FFFFFF));
}
.uc-pos {
  margin-bottom: 3px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint, #6C6A63);
}
.uc-gap {
  margin-top: 10px;
}
.uc-gl {
  line-height: 1.5;
}
.uc-rm {
  font-weight: 600;
}
.uc-ipa {
  margin-left: 4px;
  letter-spacing: 0.02em;
}
.uc-like {
  display: block;
  margin-top: 2px;
}
.uc-like .uc-ipa {
  margin-left: 0;
}
.uc-says {
  margin-top: 8px;
}
.uc-q {
  margin-top: 8px;
  padding-left: 10px;
  border-left: 2px solid var(--rule, rgba(0,0,0,0.16));
  font-size: 14.5px;
  line-height: 1.5;
}
.uc-src {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  opacity: 0.6;
}
.uc-pair {
  margin: 1px 0;
}
.uc-pl {
  font-size: 19px;
}
.uc-exw + .uc-exw {
  margin-top: 4px;
}
.uc-ex {
  font-size: 21px;
}
.uc-exr {
  font-size: 14px;
  opacity: 0.62;
}
.uc-exe {
  margin-left: 8px;
  opacity: 0.62;
}

